export function FallbackLanguage({
  requestedLocale = "{{requestedLocale}}",
  stringKey = "{{stringKey}}",
  accent = "{{accent}}",
  showNote = {{showNote}},
}) {
  const resolved = requestedLocale === "fr" ? "fr" : "en";
  const text = resolved === "fr" ? "Content de vous revoir" : "Welcome back";
  const note = requestedLocale === "de"
    ? <>de has no translation for this key &mdash; falling back to <strong style={{ color: accent }}>en</strong>.</>
    : `${requestedLocale} has its own translation, no fallback needed.`;
  return (
    <div style={{ font: "15px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099" }}>t("{stringKey}", locale: "{requestedLocale}")</p>
      <p lang={resolved} style={{ fontWeight: 700, fontSize: 18, margin: "0 0 8px" }}>{text}</p>
      {showNote && <p style={{ margin: 0, fontSize: 11, color: "#24143099" }}>{note}</p>}
    </div>
  );
}
